    /*
     * Add to the Interviewers
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Interview
     */
    public Interview addToInterviewers( UUID parentId, Employee addTo ) {
	    LOGGER.info("handling AssignInterviewersToInterviewEvent - " );
	    
	    Interview parentEntity = repository.findById(parentId).get();
	    Employee child = registry.project( Employee.class, addTo.getEmployeeId());
	    
	    parentEntity.getInterviewers().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Interviewers
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Interview
     */
	public Interview removeFromInterviewers( UUID parentId, Employee removeFrom ) {
	    LOGGER.info("handling RemoveInterviewersFromInterviewEvent " );
	
	    Interview parentEntity = repository.findById(parentId).get();
	    Employee child = registry.project( Employee.class, removeFrom.getEmployeeId());
	    
	    parentEntity.getInterviewers().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Interview via an FindInterviewQuery
     * @return 	query	FindInterviewQuery
     */
    @SuppressWarnings("unused")
    public Interview find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Interview - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Interviews
     *
     * @param	query	FindAllInterviewQuery 
     * @return 	List<Interview> 
     */
    @SuppressWarnings("unused")
    public List<Interview> findAll( FindAllInterviewQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Interview - {0}", exc.getMessage() );
    	}
    	return null;
    }


